  void deleteCaptureEventually(Path dump){for(int attempt=0;attempt<6;attempt++){try{deleteCapture(dump);return;}catch(IOException e){if(attempt<5)try{Thread.sleep(250L*(attempt+1));}catch(InterruptedException interrupted){Thread.currentThread().interrupt();return;}}}}
  void deleteFileEventually(Path file){for(int attempt=0;attempt<6;attempt++){try{Files.deleteIfExists(file);return;}catch(IOException e){if(attempt<5)try{Thread.sleep(250L*(attempt+1));}catch(InterruptedException interrupted){Thread.currentThread().interrupt();return;}}}}
  void deleteMatArtifactsEventually(Path dump){String stem=dump.getFileName().toString().replaceFirst("\\.hprof$","");for(int attempt=0;attempt<6;attempt++){try{try(var paths=Files.walk(CAPTURES)){for(Path path:paths.filter(p->!p.equals(CAPTURES)&&p.getFileName().toString().startsWith(stem+".")||p.getFileName().toString().startsWith(stem+"_")).sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}return;}catch(IOException e){if(attempt<5)try{Thread.sleep(250L*(attempt+1));}catch(InterruptedException interrupted){Thread.currentThread().interrupt();return;}}}}
