  String analyzeRecording(long id)throws Exception{byte[] data=recording(id);Path file=Files.createTempFile(CAPTURES,"jfr-",".jfr");Files.write(file,data);Map<String,Sample> methods=new HashMap<>(),allocations=new HashMap<>();int totalSamples=0;try(RecordingFile recording=new RecordingFile(file)){while(recording.hasMoreEvents()){RecordedEvent event=recording.readEvent();String type=event.getEventType().getName();if((type.equals("jdk.ExecutionSample")||type.equals("jdk.NativeMethodSample"))&&event.getStackTrace()!=null&&!event.getStackTrace().getFrames().isEmpty()){List<RecordedFrame> frames=event.getStackTrace().getFrames();RecordedFrame frame=frames.stream().filter(RecordedFrame::isJavaFrame).findFirst().orElse(frames.get(0));String className=frame.getMethod().getType().getName(),method=className+"."+frame.getMethod().getName(),stack=stack(frames);Sample sample=methods.computeIfAbsent(method,key->new Sample(className,method,frame.getLineNumber(),stack));sample.value++;totalSamples++;}else if(type.startsWith("jdk.ObjectAllocation")&&event.hasField("objectClass")){String className=event.getClass("objectClass").getName();long bytes=event.hasField("weight")?event.getLong("weight"):event.hasField("allocationSize")?event.getLong("allocationSize"):event.hasField("tlabSize")?event.getLong("tlabSize"):0;Sample sample=allocations.computeIfAbsent(className,key->new Sample(className,className,0,""));sample.value+=Math.max(0,bytes);}}}finally{Files.deleteIfExists(file);}List<Sample> hot=methods.values().stream().sorted(Comparator.comparingLong((Sample s)->s.value).reversed()).limit(25).toList(),allocated=allocations.values().stream().sorted(Comparator.comparingLong((Sample s)->s.value).reversed()).limit(25).toList();StringJoiner hotJson=new StringJoiner(",","[","]"),allocationJson=new StringJoiner(",","[","]");for(Sample sample:hot){double percent=totalSamples==0?0:sample.value*100d/totalSamples;hotJson.add("{\"method\":\""+esc(sample.name)+"\",\"samples\":"+sample.value+",\"percent\":"+String.format(Locale.ROOT,"%.2f",percent)+",\"line\":"+sample.line+",\"stack\":\""+esc(sample.stack)+"\",\"source\":"+nullable(findSource(sample.className,sample.line))+",\"hint\":\""+esc(cpuHint(sample.name))+"\"}");}for(Sample sample:allocated)allocationJson.add("{\"className\":\""+esc(sample.className)+"\",\"bytes\":"+sample.value+",\"source\":"+nullable(findSource(sample.className,0))+",\"hint\":\""+esc(memoryHint(sample.className))+"\"}");return"{\"totalSamples\":"+totalSamples+",\"hotMethods\":"+hotJson+",\"allocations\":"+allocationJson+"}";}
  String stack(List<RecordedFrame> frames){StringJoiner text=new StringJoiner(" <- ");for(RecordedFrame frame:frames.subList(0,Math.min(8,frames.size()))){String name=frame.getMethod().getType().getName()+"."+frame.getMethod().getName();text.add(name+(frame.getLineNumber()>0?":"+frame.getLineNumber():""));}return text.toString();}
  String findSource(String className,int line){String outer=className.split("\\$",2)[0],relative=outer.replace('.','/')+".java";for(String entry:runtime.getClassPath().split(java.io.File.pathSeparator)){try{Path classes=Path.of(entry);if(classes.endsWith(Path.of("target","classes"))){Path source=classes.getParent().getParent().resolve("src/main/java").resolve(relative);if(Files.isRegularFile(source))return source.toString()+(line>0?":"+line:"");}}catch(Exception ignored){}}return null;}
  public void close(){if(connector!=null)try{connector.close();}catch(IOException ignored){}}
